    html, body {
    max-width: 100%;
    overflow-x: hidden;
}

/* Container fixo no canto inferior direito */
.hover-reveal-fixed {
  position: fixed;
  bottom: 20px;
  right: 20px;
  display: flex;
  align-items: center;
  gap: 12px;
  flex-direction: row-reverse; /* Ícone à direita, texto à esquerda */
  z-index: 9; /* sempre por cima */
  cursor: pointer;
}

/* Ícone (estático agora) */
.hover-reveal-fixed .hover-icon {
  display: inline-block; /* garante que ícone se posicione corretamente */
  z-index: 2;
}

/* Texto oculto inicialmente, com sombra e animação */
.hover-reveal-fixed .reveal-text {
  opacity: 0;
  transform: translateX(40px); /* vem da direita */
  transition: opacity 0.4s ease, transform 0.4s ease;
  white-space: nowrap;
  position: relative;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 1); /* sombra suave */
  color: #fff; /* opcional: cor branca para contraste */
  z-index: 2;
}

/* Hover: apenas o texto aparece */
.hover-reveal-fixed:hover .reveal-text {
  opacity: 1;
  transform: translateX(0);
}
